/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {createContext, useContext, useEffect, useMemo, useState} from 'react';
import {AsideHeader} from '@gravity-ui/navigation';
import {DashKit, type DashKitProps, type PluginWidgetProps} from '@gravity-ui/dashkit';
import {Chart, type ChartData} from '@gravity-ui/charts';
import {Button, Icon, Text, Modal, Select, TextInput, DropdownMenu, configure} from '@gravity-ui/uikit';
import {LayoutCellsLarge, ChartLine, ChartColumn, Persons, Database, Gear, CircleQuestion, Bell, ChevronDown, ChevronRight, Plus, Calendar, Sliders, ArrowUpRight, ArrowDownRight, ArrowDownToLine, ArrowRight, Grip, Ellipsis, Xmark, CircleCheck, Clock, Copy, TrashBin, ArrowRotateLeft, Magnifier, Target, Globe} from '@gravity-ui/icons';
import './styles.css';

configure({lang: 'ru'});
type Config = DashKitProps['config'];
type WidgetKind = 'revenue' | 'orders' | 'visitors' | 'conversion' | 'sales' | 'audience' | 'sources' | 'products' | 'activity' | 'goal';
const widgetCatalog: {kind: WidgetKind; title: string; description: string; icon: typeof ChartLine; category: string}[] = [
  {kind: 'revenue', title: 'Выручка', description: 'Доход и изменение за выбранный период', icon: ChartColumn, category: 'Показатели'},
  {kind: 'orders', title: 'Заказы', description: 'Количество заказов и динамика продаж', icon: LayoutCellsLarge, category: 'Показатели'},
  {kind: 'visitors', title: 'Посетители', description: 'Аудитория вашего сайта в цифрах', icon: Persons, category: 'Показатели'},
  {kind: 'conversion', title: 'Конверсия', description: 'Доля посетителей, совершивших покупку', icon: Target, category: 'Показатели'},
  {kind: 'sales', title: 'Динамика выручки', description: 'Сравнение с предыдущим периодом', icon: ChartLine, category: 'Графики'},
  {kind: 'audience', title: 'Источники трафика', description: 'Распределение посетителей по каналам', icon: Globe, category: 'Графики'},
  {kind: 'sources', title: 'Каналы привлечения', description: 'Эффективность ваших источников трафика', icon: ArrowUpRight, category: 'Таблицы'},
  {kind: 'products', title: 'Популярные продукты', description: 'Продукты, которые выбирают чаще всего', icon: LayoutCellsLarge, category: 'Таблицы'},
  {kind: 'activity', title: 'Последние события', description: 'Что происходит в вашем бизнесе', icon: Clock, category: 'Другое'},
  {kind: 'goal', title: 'Цель по выручке', description: 'Прогресс на пути к месячной цели', icon: Target, category: 'Другое'},
];
const initialKinds: WidgetKind[] = ['revenue', 'orders', 'visitors', 'conversion', 'sales', 'audience', 'sources', 'products', 'activity'];
const initialConfig: Config = {
  salt: 'orbit', counter: 9, aliases: {}, connections: [],
  items: initialKinds.map((kind, i) => ({id: "'`widget-${i}`, type: '"'orbit-widget', namespace: 'default', data: {kind}})),
  layout: initialKinds.map((kind, i) => ({i: "'`widget-${i}`, x: i < 4 ? i * 9 : i === 4 ? 0 : i === 5 ? 24 : (i - 6) * 12, y: i < 4 ? 0 : i < 6 ? 5 : 15, w: i < 4 ? 9 : i === 4 ? 24 : 12, h: i < 4 ? 5 : i < 6 ? 11 : 10, minW: 6, minH: i < 4 ? 5 : 8})),
};
const STORE = '"'orbit-dashboard-v1';
function readConfig(): Config {try {const stored = JSON.parse(localStorage.getItem(STORE) || 'null'); if (stored?.items && stored?.layout && stored?.salt) return stored;} catch {} return initialConfig;}
const DashboardContext = createContext({period: '30', edit: false, remove: (_id: string) => {}, duplicate: (_id: string) => {}, detail: (_kind: string) => {}});
const color = (token: string) => "'`var(--g-color-${token})`;
const trends = [12, 11, 15, 13, 19, 17, 21, 15, 24, 22, 29, 26, 31, 29, 35, 31, 39];
function Sparkline({index}: {index: number}) {
  const points = trends.map((v, i) => ({x: i, y: v + Math.sin(i * (index + 1)) * 5}));
  const data: ChartData = {chart: {margin: 0}, legend: {enabled: false}, tooltip: {enabled: false}, xAxis: {visible: false}, yAxis: [{visible: false}], series: {data: [{type: '"'area', name: 'Динамика', data: points, color: color(index === 3 ? 'line-warning' : 'base-brand'), opacity: 0.09, lineWidth: 1.8}]}};
  return <div className=\"sparkline\"><Chart data={data}/></div>;
}
function Metric({kind}: {kind: WidgetKind}) {
  const {period} = useContext(DashboardContext);
  const index = ['revenue', 'orders', 'visitors', 'conversion'].indexOf(kind);
  const ratio = period === '7' ? .26 : period === '90' ? 2.87 : 1;
  const metrics = [
    {title: 'Выручка', value: "'`${Math.round(1284560 * ratio).toLocaleString('"'ru-RU')} ₽"'`, change: '"'12,8', icon: ChartColumn},
    {title: 'Заказы', value: Math.round(1842 * ratio).toLocaleString('ru-RU'), change: '8,2', icon: LayoutCellsLarge},
    {title: 'Посетители', value: Math.round(24839 * ratio).toLocaleString('ru-RU'), change: '16,4', icon: Persons},
    {title: 'Конверсия', value: period === '7' ? '3,62%' : '3,84%', change: '0,6', icon: Target},
  ];
  const metric = metrics[index];
  return <><div className=\"metric-label\"><span>{metric.title}</span><Icon data={metric.icon} size={16}/></div><Text variant=\"display-1\" className=\"metric-value\">{metric.value}</Text><div className=\"metric-footer\"><span className={"'`change ${index === 3 ? '"'negative' : ''}"'`}><Icon data={index === 3 ? ArrowDownRight : ArrowUpRight} size={13}/>{metric.change}%</span><span className="versus">к прошлому периоду</span></div><Sparkline index={index}/></>;
}
const sourceNames = ['"'Прямые переходы', 'Поисковые системы', 'Социальные сети', 'Другое'];
const sourceColors = ['base-brand', 'data-secondary', 'data-tertiary', 'data-quaternary'];
function SalesChart() {
  const {period} = useContext(DashboardContext);
  const [mode, setMode] = useState('days');
  const ratio = period === '7' ? .66 : period === '90' ? 1.4 : 1;
  const values = mode === 'days' ? [23, 28, 25, 24, 35, 30, 27, 39, 43, 38, 40, 34, 41, 47, 40, 43, 37, 46, 53, 45, 49, 41, 48, 60, 53, 56, 51, 58, 66, 61] : [25, 32, 38, 44, 58];
  const data: ChartData = {chart: {margin: {top: 10, right: 8, bottom: 5, left: 4}}, legend: {enabled: false}, xAxis: {type: 'category', categories: values.map((_, i) => mode === 'days' ? "'`${i + 1} окт` : `${i + 1} нед`), ticks: {pixelInterval: 85}, grid: {enabled: false}, lineColor: color('"'line-generic')}, yAxis: [{min: 0, max: 80, ticks: {pixelInterval: 48}, grid: {enabled: true}, labels: {numberFormat: {suffix: ' тыс.'}}, title: {text: ''}}], series: {data: [{type: 'area', name: 'Текущий период', data: values.map((y, x) => ({x, y: y * ratio})), color: color('base-brand'), opacity: .07, lineWidth: 2.5}, {type: 'line', name: 'Предыдущий период', data: values.map((y, x) => ({x, y: (y * .64 + Math.sin(x * 1.5) * 7) * ratio})), color: color('data-secondary'), lineWidth: 2, dashStyle: 'Dash'}]}};
  return <><div className=\"sales-summary\"><div><Text variant=\"display-1\">{Math.round(1284560 * (period === '7' ? .26 : period === '90' ? 2.87 : 1)).toLocaleString('ru-RU')} ₽</Text><span className=\"change\"><Icon data={ArrowUpRight} size={13}/>12,8%</span></div><Select size=\"s\" value={[mode]} onUpdate={v => setMode(v[0])} options={[{value:'days', content:'По дням'}, {value:'weeks', content:'По неделям'}]}/></div><div className=\"sales-chart\"><Chart data={data}/></div><div className=\"chart-legend\"><span><i/>Текущий период</span><span><i className=\"previous\"/>Предыдущий период</span></div></>;
}
function Audience() {
  const {period} = useContext(DashboardContext);
  const data: ChartData = {chart: {margin: 0}, legend: {enabled: false}, series: {data: [{type: 'pie', innerRadius: '77%', radius: '96%', borderWidth: 3, dataLabels: {enabled: false}, data: [42, 28, 18, 12].map((value, i) => ({name: sourceNames[i], value, color: color(sourceColors[i])}))}]}};
  return <><div className=\"donut\"><Chart data={data}/><div className=\"donut-label\"><Text variant=\"header-1\">{Math.round(24839 * (period === '7' ? .26 : period === '90' ? 2.87 : 1)).toLocaleString('ru-RU')}</Text><span>посетителей</span></div></div><div className=\"audience-legend\">{sourceNames.map((name, i) => <div key={name}><span><i style={{background:color(sourceColors[i])}}/>{name}</span><b>{[42,28,18,12][i]}%</b></div>)}</div></>;
}
function Sources() {
  return <div className=\"source-table\"><div className=\"table-head\"><span>Канал</span><span>Посетители</span><span>Динамика</span></div>{[['Google','8 942','18,6','G'],['Яндекс','6 218','12,4','Я'],['Telegram','4 105','24,8','↗'],['Instagram','2 894','8,2','◎']].map(([name,value,delta,letter], i) => <div className=\"source-row\" key={name}><span className=\"source-name\"><span className={"'`source-icon source-${i}`}>{letter}</span>{name}</span><b>{value}</b><span className="positive">+{delta}%</span></div>)}<div className="widget-bottom">Всего 8 каналов<Icon data={ArrowRight} size={14}/></div></div>;
}
function Products() {
  return <div className="products">{[['"'Pro подписка','842 продажи','584 600 ₽','pro',81],['Базовая подписка','628 продаж','376 800 ₽','basic',61],['Командный план','214 продаж','256 800 ₽','team',42],['Дополнения','158 продаж','66 360 ₽','extra',23]].map(([name,sales,total,tone,width]) => <div className=\"product-row\" key={name}><div className={"'`product-icon ${tone}`}><Icon data={tone === '"'team' ? Persons : tone === 'extra' ? Plus : LayoutCellsLarge} size={17}/></div><div className=\"product-info\"><div><b>{name}</b><strong>{total}</strong></div><div className=\"product-meta\"><span>{sales}</span><div className=\"mini-track\"><i style={{width:"'`${width}%`}}/></div></div></div></div>)}</div>;
}
function Activity() {
  return <div className="activities">{[{title:'"'Новый заказ #1048',desc:'Pro подписка · 6 900 ₽',time:'2 мин назад',icon:LayoutCellsLarge,tone:'coral'}, {title:'Новый пользователь',desc:'Анна Смирнова',time:'15 мин назад',icon:Persons,tone:'green'},{title:'Цель почти достигнута',desc:'80% от месячного плана',time:'42 мин назад',icon:Target,tone:'amber'},{title:'Отчёт за сентябрь готов',desc:'Доступен для скачивания',time:'1 час назад',icon:ChartColumn,tone:'blue'}].map(event => <div className=\"activity-row\" key={event.title}><div className={"'`event-icon ${event.tone}`}><Icon data={event.icon} size={15}/></div><div className="event-info"><b>{event.title}</b><span>{event.desc}</span></div><span className="event-time">{event.time}</span></div>)}</div>;
}
function Widget({id, data}: PluginWidgetProps) {
  const {edit, remove, duplicate, detail} = useContext(DashboardContext);
  const kind = data.kind as WidgetKind;
  const isMetric = ['"'revenue','orders','visitors','conversion'].includes(kind);
  const title = widgetCatalog.find(w => w.kind === kind)?.title || 'Виджет';
  return <article className={"'`widget ${isMetric ? '"'metric-widget' : ''} widget-"'${kind} ${edit ? '"'is-editing' : ''}"'`}>
    {isMetric ? <><div className="metric-drag widget-drag-handle" title="Перетащить виджет"/><Metric kind={kind}/>{edit && <Button className="metric-remove" view="flat" size="s" onClick={() => remove(id)} aria-label="Удалить виджет"><Icon data={Xmark} size={13}/></Button>}</> : <><div className="widget-header"><div className="widget-title widget-drag-handle"><Icon data={Grip} size={14}/><Text variant="subheader-2">{title}</Text></div><DropdownMenu defaultSwitcherProps={{view:'"'flat',size:'s','aria-label':"'`Действия: ${title}`}} items={[{text:'"'Подробнее',action:() => detail(kind)},{text:'Дублировать',action:() => duplicate(id),iconStart:<Icon data={Copy} size={14}/>},{text:'Удалить виджет',action:() => remove(id),theme:'danger',iconStart:<Icon data={TrashBin} size={14}/>} ]}/></div><div className=\"widget-content\">{kind === 'sales' ? <SalesChart/> : kind === 'audience' ? <Audience/> : kind === 'sources' ? <Sources/> : kind === 'products' ? <Products/> : kind === 'activity' ? <Activity/> : <div className=\"goal-content\"><Text variant=\"display-2\">80%</Text><Text variant=\"body-2\">1 284 560 ₽ из 1 600 000 ₽</Text><div className=\"goal-track\"><i/></div><span>До цели осталось 315 440 ₽</span></div>}</div></>}
  </article>;
}
DashKit.setSettings({gridLayout: {cols: 36, rowHeight: 10, margin: [20,20], containerPadding: [0,0], compactType: 'vertical'}, isMobile: false});
DashKit.registerPlugins({type:'orbit-widget', defaultLayout:{w:12,h:10,minW:6,minH:5}, renderer: props => <Widget {...props}/>});

export function App() {
  const [config,setConfig] = useState<Config>(readConfig);
  const [edit,setEdit] = useState(false);
  const [compact,setCompact] = useState(window.innerWidth < 1000);
  const [narrow,setNarrow] = useState(window.innerWidth < 700);
  const [period,setPeriod] = useState('30');
  const [tab,setTab] = useState('overview');
  const [catalog,setCatalog] = useState(false);
  const [query,setQuery] = useState('');
  const [category,setCategory] = useState('Все');
  const [dialog,setDialog] = useState<string | null>(null);
  const [toast,setToast] = useState('');
  const [workspace,setWorkspace] = useState('Студия Дизайн');
  const [saved,setSaved] = useState(true);
  useEffect(() => {const resize=()=>{setNarrow(window.innerWidth<700);if(window.innerWidth<1000)setCompact(true);};window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize);},[]);
  useEffect(() => {try {localStorage.setItem(STORE, JSON.stringify(config));setSaved(true);} catch {setSaved(false);}},[config]);
  useEffect(() => {if("'!toast)return;const timer=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(timer);},[toast]);
  const remove = (id:string) => {setConfig(current => DashKit.removeItem({id,config:current,itemsStateAndParams:{}}).config);setToast('Виджет удалён');};
  const addWidget = (kind:WidgetKind) => {setConfig(current => DashKit.setItem({config:current,item:{type:'orbit-widget',namespace:'default',data:{kind},layout:{x:0,y:Math.max(0,...current.layout.map(l=>l.y+l.h)),w:kind==='sales'?24:12,h:['revenue','orders','visitors','conversion'].includes(kind)?5:10}}}));setCatalog(false);setToast('Виджет добавлен на дашборд');};
  const duplicate = (id:string) => {const item=config.items.find(w=>w.id===id);if(item)addWidget(item.data.kind as WidgetKind);};
  const context = {period,edit,remove,duplicate,detail:(kind:string)=>setDialog(kind)};
  const mobileConfig = useMemo(()=>({...config,layout:config.layout.map((item,index)=>({...item,x:0,y:index*11,w:36,h:index<4?5:11,minW:36}))}),[config]);
  const exportReport = () => {const csv='\\uFEFFПоказатель;Значение\\nВыручка;1284560\\nЗаказы;1842\\nПосетители;24839\\nКонверсия;3.84\\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='orbit-report.csv';a.click();URL.revokeObjectURL(url);setToast('Отчёт скачан');};
  const navItems=[{id:'overview',title:'Обзор',icon:LayoutCellsLarge},{id:'analytics',title:'Аналитика',icon:ChartLine},{id:'audience',title:'Аудитория',icon:Persons},{id:'reports',title:'Отчёты',icon:ChartColumn},{id:'data',title:'Источники данных',icon:Database}];
  return <DashboardContext.Provider value={context}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton hideSectionDividers logo={{text:()=> <span className=\"brand-name\">orbit<span className=\"brand-dot\">.</span></span>,icon:LayoutCellsLarge,onClick:()=>setTab('overview')}} aboveMenuContent={<><div className=\"workspace-picker\">{"'!compact ? <DropdownMenu renderSwitcher={props=><Button {...props} view="outlined" size="xl" width="max"><span className="workspace-avatar">С</span><span className="workspace-label">{workspace}<small>Рабочее пространство</small></span><Icon data={ChevronDown} size={14}/></Button>} items={['"'Студия Дизайн','Личное пространство'].map(name=>({text:name,action:()=>{setWorkspace(name);setToast("'`Выбрано: ${name}`);}}))}/> : <Button view="flat" onClick={()=>setCompact(false)} aria-label="Развернуть меню"><span className="workspace-avatar">С</span></Button>}</div>{!compact&&<div className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div>}</>} menuItems={navItems.map(item=>({...item,current:tab===item.id,onItemClick:()=>setTab(item.id),className:'"'navigation-item'}))} renderFooter={()=> <div className=\"sidebar-footer\">{"'!compact&&<div className="plan-card"><span className="plan-icon">✧</span><b>Больше возможностей</b><p>Все данные. Больше виджетов.<br/>Никаких ограничений.</p><Button view="outlined" size="l" width="max" onClick={()=>setDialog('"'plan')}>Открыть Pro<Icon data={ArrowUpRight} size={15}/></Button></div>}<Button className=\"sidebar-link\" view=\"flat\" width=\"max\" onClick={()=>setDialog('settings')}><Icon data={Gear} size={18}/>{"'!compact&&'"'Настройки'}</Button><Button className=\"sidebar-link\" view=\"flat\" width=\"max\" onClick={()=>setDialog('help')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button>{"'!compact&&<div className="sidebar-signature"><span className="live-dot"/>Все системы работают<span>↗</span></div>}</div>} renderContent={()=> <div className="page"><header className="topbar"><div className="breadcrumbs"><Button view="flat" size="s" onClick={()=>setCompact(!compact)} aria-label="Свернуть или развернуть меню"><Icon data={LayoutCellsLarge} size={16}/></Button><span className="breadcrumb-divider"/><span>Рабочее пространство</span><Icon data={ChevronRight} size={12}/><b>{navItems.find(n=>n.id===tab)?.title}</b></div><div className="topbar-right"><span className="demo-tag">Демо-данные</span><Button className="notification-button" view="flat" onClick={()=>setDialog('"'notifications')} aria-label=\"Уведомления\"><Icon data={Bell} size={18}/><i/></Button><span className=\"topbar-divider\"/><DropdownMenu renderSwitcher={props=><Button {...props} view=\"flat\" size=\"l\" aria-label=\"Профиль\"><span className=\"profile-avatar\">АК</span><Icon data={ChevronDown} size={12}/></Button>} items={[{text:'Алексей Козлов · Владелец',action:()=>setDialog('profile')},{text:'Настройки профиля',action:()=>setDialog('settings')} ]}/></div></header><main className=\"main-content\"><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ БИЗНЕС В ОДНОМ МЕСТЕ</div><Text variant=\"display-2\" className=\"page-title\">{tab==='overview'?'Обзор бизнеса':navItems.find(n=>n.id===tab)?.title}</Text><p>Всё важное — на вашем дашборде. Настройте его под себя.</p></div><Button view=\"outlined\" size=\"l\" onClick={exportReport}><Icon data={ArrowDownToLine} size={16}/>Экспорт</Button></div><div className=\"dashboard-tabs\"><div className=\"dashboard-tab\"><span className=\"tab-symbol\"><Icon data={LayoutCellsLarge} size={15}/></span>Основной дашборд<span className=\"tab-count\">{config.items.length}</span></div><Button view=\"flat-secondary\" size=\"s\" onClick={()=>setDialog('new-dashboard')} aria-label=\"Создать дашборд\"><Icon data={Plus} size={16}/></Button><span className=\"saved-status\"><Icon data={CircleCheck} size={13}/>{saved?'Все изменения сохранены':'Не удалось сохранить'}</span></div><div className=\"dashboard-toolbar\"><div className=\"toolbar-left\"><Select className=\"period-select\" value={[period]} onUpdate={v=>setPeriod(v[0])} options={[{value:'7',content:'Последние 7 дней'},{value:'30',content:'Последние 30 дней'},{value:'90',content:'Последние 90 дней'}]} size=\"m\"/><span className=\"date-caption\"><Icon data={Calendar} size={14}/>{period==='7'?'25–31 окт. 2024':period==='90'?'3 авг. – 31 окт. 2024':'1 окт. – 31 окт. 2024'}</span></div><div className=\"toolbar-right\"><Button view={edit?'outlined-action':'outlined'} selected={edit} size=\"m\" onClick={()=>{setEdit("'!edit);if(edit)setToast('"'Расположение виджетов сохранено');}}><Icon data={edit?CircleCheck:Sliders} size={15}/>{edit?'Готово':'Настроить'}</Button><Button view=\"action\" size=\"m\" onClick={()=>{setQuery('');setCatalog(true);}}><Icon data={Plus} size={16}/>Добавить виджет</Button></div></div>{edit&&<div className=\"edit-notice\"><Icon data={Grip} size={16}/><span>Перетаскивайте виджеты за заголовок и меняйте размер за нижний угол.</span><Button view=\"flat\" size=\"s\" onClick={()=>{setConfig(initialConfig);setToast('Начальное расположение восстановлено');}}><Icon data={ArrowRotateLeft} size={14}/>Сбросить</Button></div>}<div className=\"dashboard-grid\">{config.items.length ? <DashKit key={narrow?'mobile':'desktop'} config={narrow?mobileConfig:config} editMode={edit&&"'!narrow} noOverlay draggableHandleClassName="widget-drag-handle" onChange={({config:next})=>{if(!narrow)setConfig(next);}}/> : <div className="empty-state"><Icon data={LayoutCellsLarge} size={36}/><Text variant="header-1">Ваш дашборд — чистый лист</Text><p>Добавьте первый виджет, чтобы увидеть свои показатели.</p><Button view="action" onClick={()=>setCatalog(true)}>Добавить виджет</Button></div>}</div><footer className="page-footer"><span><span className="live-dot"/>Обновлено только что <span className="footer-separator">·</span> Данные обновляются каждые 5 минут</span><span>Сделано для ясности<span className="footer-orbit">orbit.</span></span></footer></main></div>}/>
